{
  "concepts": [
    {
      "conditions": [
        "Claims about exact subjects are relied on for promotion, closure or release.",
        "Finite evidence may concern a weaker or different subject or basis.",
        "Constructors may be probabilistic or otherwise fallible.",
        "Each reliance boundary has a decision owner."
      ],
      "definition": "F6 is the source's claims, evidence, assessment and acceptance family, covering EVALUATION §§1–5. Its instance premises are conditions of governed work, not commitments or consequences of finite capacity alone. Its foundation table traces consequences and separately identifies added policy choices and their owners.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 75,
          "quote": "They are conditions of the work\nthis family governs, not commitments, and do not follow from finite\ncapacity alone.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F1.%20Claims%2FFoundation%20to%20law%3A%20claims%2C%20evidence%2C%20assessment%20and%20acceptance",
          "start_line": 73
        }
      ],
      "key": "claims_evidence_family",
      "label": "Claims, evidence, assessment and acceptance"
    },
    {
      "conditions": [],
      "definition": "A load-bearing claim identifies an exact subject, claimed property, governing basis, witness-to-claim relation, nearest excluded weaker property and falsifier. Its evidence boundary, population and quantification are part of its meaning.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 82,
          "quote": "a load-bearing claim names its exact subject, the property claimed, the governing basis, the relation between witness and claim, the nearest weaker property it excludes and its falsifier before a witness is selected",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F1.%20Claims%2FFoundation%20to%20law%3A%20claims%2C%20evidence%2C%20assessment%20and%20acceptance",
          "start_line": 82
        }
      ],
      "key": "load_bearing_claim",
      "label": "Load-bearing claim"
    },
    {
      "conditions": [],
      "definition": "The constitutional and accepted-design relations defining a claim's meaning.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 135,
          "quote": "the semantic basis, the constitutional\nand accepted-design relations that define what a claim means",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F2.%20Separation",
          "start_line": 134
        }
      ],
      "key": "semantic_basis",
      "label": "Semantic basis"
    },
    {
      "conditions": [],
      "definition": "The exact artifacts, events, logs, tests and observations used to evaluate a claim.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 137,
          "quote": "the evidence\nbasis, the exact artifacts, events, logs, tests and observations used to\nevaluate it",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F2.%20Separation",
          "start_line": 135
        }
      ],
      "key": "evidence_basis",
      "label": "Evidence basis"
    },
    {
      "conditions": [],
      "definition": "A current view derived from admitted semantic and evidence bases.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 138,
          "quote": "the state projection, a current view derived from admitted\nsemantic and evidence bases.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F2.%20Separation",
          "start_line": 137
        }
      ],
      "key": "state_projection",
      "label": "State projection"
    },
    {
      "conditions": [],
      "definition": "Structural conformance decides closed syntax, types, identities, references, bases and mechanically decidable predicates; semantic fidelity decides meaning and materiality. These are separate claims, including in a_c models.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 163,
          "quote": "Structural conformance decides closed syntax, types, identities, references,\nbases and mechanically decidable predicates. Semantic fidelity decides\nmeaning and materiality.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F2.%20Separation",
          "start_line": 161
        }
      ],
      "key": "structural_and_semantic_claims",
      "label": "Structural conformance and semantic fidelity"
    },
    {
      "conditions": [],
      "definition": "Assessment independent of the reviewed subject's authorship and satisfying the declared evidence conditions. This section defines independence; TICKETS owns the method's required assessment boundaries, and a governing basis may add boundaries.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 190,
          "quote": "This section decides what counts as independent assessment. Which\nboundaries require it is a policy choice of the Spec Method, owned by\n[TICKETS §7 Execution and verification authority separation](TICKETS.md#execution-and-verification-authority-separation-up-007);\na governing basis may add boundaries.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F3.%20Independent%20assessment",
          "start_line": 187
        }
      ],
      "key": "independent_assessment",
      "label": "Independent assessment"
    },
    {
      "conditions": [],
      "definition": "The party responsible for the content of a realised subject, including a contribution carried elsewhere.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 218,
          "quote": "Author identity is the party responsible for the content of a realised\nsubject.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F3.%20Independent%20assessment",
          "start_line": 217
        }
      ],
      "key": "author_identity",
      "label": "Author identity"
    },
    {
      "conditions": [],
      "definition": "The identity of whoever performs an operation; actor identity is not itself authority and is distinct from responsibility for authored content.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 219,
          "quote": "It is distinct from actor identity, whoever performs one\noperation, which is an identity and not an authority",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F3.%20Independent%20assessment",
          "start_line": 218
        }
      ],
      "key": "actor_identity",
      "label": "Actor identity"
    },
    {
      "conditions": [],
      "definition": "A review's per-evaluated-predicate core result together with exact subject and basis, consulted evidence, consequence-ranked findings, each finding's evidence and smallest bounded correction, residual uncertainty and invalidation conditions. A chaseable evidentiary finding differs from commentary.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 249,
          "quote": "A review returns one core result\n([FOUNDATIONS §4, Results](FOUNDATIONS.md#results)) for each declared\npredicate it evaluated, with: the exact subject and basis, the evidence\nconsulted, the findings ranked by consequence, each finding's evidence and\nthe smallest bounded correction, the residual uncertainty, and the\ninvalidation conditions.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F4.%20Review%20results",
          "start_line": 244
        }
      ],
      "key": "review_result",
      "label": "Review result"
    },
    {
      "conditions": [
        "A predicate was evaluated."
      ],
      "definition": "The five core values projected by review triage are satisfied, falsified, indeterminate, out_of_frame and invalid_basis. An unperformed predicate has no result and is outside this projection's domain.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 283,
          "quote": "The projection of the finding-level triage payload is total over the core\nvalues of [FOUNDATIONS §4, Results](FOUNDATIONS.md#results). A predicate\nnot performed has no result and so no triage payload",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F4.%20Review%20results%2FResult%20and%20triage%20projection",
          "start_line": 278
        },
        {
          "end_line": 291,
          "quote": "| invalid_basis | a basis failure; triage `not_applicable`; invalidation evidence and basis-repair pressure | refuse to consume the result and return through the declared basis re-entry relation |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F4.%20Review%20results%2FResult%20and%20triage%20projection",
          "start_line": 291
        }
      ],
      "key": "core_review_values",
      "label": "Core review result domain"
    },
    {
      "conditions": [
        "A review returns findings with technical triage."
      ],
      "definition": "The assessor's evidence-bound assessment of each finding against the exact evaluated claim and basis. Severity is the assessor's grade of consequence. Triage payload classes complete, indeterminate and not_applicable classify payloads, not results, dispositions, priorities or lifecycle states.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 266,
          "quote": "Where a review returns findings with technical triage, the triage is the\nassessor's evidence-bound assessment of each finding against the exact\nevaluated claim and basis. Severity, the assessor's grade of consequence,\nis evaluation evidence.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F4.%20Review%20results%2FResult%20and%20triage%20projection",
          "start_line": 263
        }
      ],
      "key": "technical_triage",
      "label": "Technical triage"
    },
    {
      "conditions": [],
      "definition": "The owner of priority, current promotion-boundary effect and disposition, receiving assessment evidence without mechanically adopting its recommended disposition.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 273,
          "quote": "Priority, the effect on the current promotion\nboundary and the disposition are the decision owner's",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F4.%20Review%20results%2FResult%20and%20triage%20projection",
          "start_line": 266
        }
      ],
      "key": "decision_owner",
      "label": "Decision owner"
    },
    {
      "conditions": [
        "The subject remains unchanged from the evaluated subject."
      ],
      "definition": "The decision owner's disposition over the evaluated subject, limited to the named instance and interval. Recording acceptance does not widen it.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 314,
          "quote": "Acceptance is the decision owner's disposition over an unchanged subject;\nrecording it cannot widen it, and it exhausts only the instance and interval\nit names",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F5.%20Acceptance",
          "start_line": 312
        }
      ],
      "key": "acceptance",
      "label": "Acceptance"
    },
    {
      "conditions": [
        "The accepted subject is a successor."
      ],
      "definition": "Acceptance evidence naming the exact predecessor immutable cut and one semantic disposition for every predecessor claim capable of affecting the successor. RELEASE §9 owns disposition values and evaluation of the record.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 336,
          "quote": "the exact predecessor immutable cut\nthe successor evolves, and one semantic disposition for every predecessor\nclaim capable of affecting the successor.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F5.%20Acceptance",
          "start_line": 332
        }
      ],
      "key": "successor_disposition_record",
      "label": "Successor disposition record"
    },
    {
      "conditions": [],
      "definition": "Blocking current promotion is the decision owner's act over a defect reported against the exact evaluated claim. EVALUATION §5 owns the blocking rule; profiles and work carriers add only domain triggers.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 346,
          "quote": "A finding is a defect a review reports against the exact claim it\nevaluated (§4). Blocking current promotion is the decision owner's act\nover that finding (§4, Result and triage projection). This section is the\none statement of when a finding can block; profiles and work carriers\nrefer to it and add only their domain triggers.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F5.%20Acceptance%2FWhen%20a%20finding%20blocks%20promotion",
          "start_line": 342
        }
      ],
      "key": "promotion_blocking",
      "label": "Finding-relative promotion blocking"
    },
    {
      "conditions": [
        "Behaviour is interpreted under a declared interpretation contract.",
        "There is an independent judgment."
      ],
      "definition": "A realisation conforms to specification Σ when its interpreted behaviour satisfies Σ. Semantic conformance uses the governing semantic basis as Σ. Several realisations may conform; conformance does not establish equal cost or identical behaviour outside Σ.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 393,
          "quote": "A realisation aⱼ conforms to a specification Σ when its interpreted behaviour\nsatisfies Σ under a declared interpretation contract (P1) and an independent\njudgment (P6).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F6.%20Conformance%20of%20realisations",
          "start_line": 388
        }
      ],
      "key": "realisation_conformance",
      "label": "Conformance of realisations"
    },
    {
      "conditions": [
        "A domain is stated."
      ],
      "definition": "Identical interpreted behaviour on the stated domain, including behaviour outside Σ, between two realisations or between a realisation and a declared reference outcome. This is not cross-context equivalence of concepts.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 405,
          "quote": "Semantic equivalence of realisations claims that two\nrealisations, or a realisation and a declared reference outcome, have\nidentical interpreted behaviour on a stated domain, behaviour outside Σ\nincluded.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F6.%20Conformance%20of%20realisations",
          "start_line": 400
        }
      ],
      "key": "semantic_equivalence",
      "label": "Semantic equivalence of realisations"
    },
    {
      "conditions": [
        "Workloads and architecture H are declared."
      ],
      "definition": "Two realisations compute the same function at equal cost for the declared workloads on H.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 410,
          "quote": "Computational\nequivalence claims that two realisations compute the same function at\nequal cost for declared workloads on a declared architecture H.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F6.%20Conformance%20of%20realisations",
          "start_line": 408
        }
      ],
      "key": "computational_equivalence",
      "label": "Computational equivalence"
    },
    {
      "conditions": [
        "A domain is stated.",
        "Every applicable requirement of the referenced Formal fragment is met."
      ],
      "definition": "Equivalence of categories and maps, additionally requiring a quasi-inverse functor and natural isomorphisms from both functor/quasi-inverse composites to the corresponding identity functors. Preservation of identities and composition by a map is a further, separate claim.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 423,
          "quote": "This rung adds one\nrequirement of its own to those items: a quasi-inverse functor, and\nnatural isomorphisms between each composite of the functor with its\nquasi-inverse and the identity functor, on a stated domain.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F6.%20Conformance%20of%20realisations",
          "start_line": 419
        }
      ],
      "key": "categorical_equivalence",
      "label": "Categorical equivalence and distinct structure-preservation claim"
    },
    {
      "conditions": [
        "A specification is arranged in layers."
      ],
      "definition": "A competent actor can derive a conformant next layer from each layer. Sufficiency requires a correct reconstruction route, not unique derivation or execution on every use.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 431,
          "quote": "A specification arranged in layers is sufficient when\na competent actor can derive a conformant next layer from each layer; the\nderivation need not be unique",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F6.%20Conformance%20of%20realisations",
          "start_line": 428
        }
      ],
      "key": "layered_sufficiency",
      "label": "Layered sufficiency"
    },
    {
      "conditions": [
        "A task builds or assesses one successor member against its predecessor."
      ],
      "definition": "A return with three separate claim-and-evidence heads: semantic conservation preserves a disposed predecessor claim's meaning, judged from both texts against its disposition; demonstrated reduction traces a lower-cost successor deciding path against the same predecessor path on a declared measure with tradeoffs; mere relocation moves text between owners or carriers without changed meaning or a traced deciding-path change.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 478,
          "quote": "Mere relocation: text moved from one owner or\ncarrier to another without a change in meaning and without a traced\nchange in any deciding path.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F6.%20Conformance%20of%20realisations%2FReturn%20of%20a%20reconstruction",
          "start_line": 476
        }
      ],
      "key": "reconstruction_return",
      "label": "Return of a reconstruction"
    },
    {
      "conditions": [
        "One specification may have several realisations.",
        "Realisations, frames and methods are made by fallible constructors and relied on by other actors.",
        "Qualification evidence comprises finite cases run inside declared actor envelopes."
      ],
      "definition": "F7 covers EVALUATION §§6–7 and CONFORMANCE, addressing fitness of realisations, frames and the method for their claims. Its instance premises are conditions, not commitments or derivations from finite capacity. Its cited P0 actor-change premise allows a next actor to reacquire declared sources, not private memory.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 501,
          "quote": "P0's actor-change premise, that the actor of one\nstep need not be the actor of the next and may re-acquire declared sources\nbut not private memory, is cited by name.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F6.%20Conformance%20of%20realisations%2FFoundation%20to%20law%3A%20conformance%2C%20equivalence%20and%20qualification",
          "start_line": 497
        }
      ],
      "key": "conformance_qualification_family",
      "label": "Conformance, equivalence and qualification"
    },
    {
      "conditions": [],
      "definition": "The document container for qualification of frames and of the method; this heading itself supplies no additional qualification predicate.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 545,
          "quote": "## 7. Qualification of frames and of the method",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F7.%20Qualification%20of%20frames%20and%20of%20the%20method",
          "start_line": 545
        }
      ],
      "key": "qualification_section",
      "label": "Qualification section"
    },
    {
      "conditions": [],
      "definition": "Qualification of a candidate frame proportional to its claims, using at least decision, reconstruction, sensitivity, irrelevance, basis, authority, counterexample, capability and result-consumption tests.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 552,
          "quote": "A candidate frame ([REFERENCE_FRAME](REFERENCE_FRAME.md)) is qualified in\nproportion to its claims",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F7.%20Qualification%20of%20frames%20and%20of%20the%20method%2FFrame%20qualification",
          "start_line": 549
        }
      ],
      "key": "frame_qualification",
      "label": "Frame qualification"
    },
    {
      "conditions": [
        "For the context dimension, selected representation size is measured against declared capacity."
      ],
      "definition": "Fit concerns whether the declared actor class can hold the frame; other envelope dimensions are fitted under RF-014. Fit is distinct from adequate attention.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 585,
          "quote": "Whether the declared actor class can hold the frame\nis fit: for the context dimension, the size of the selected\nrepresentation, measured as ACTIVATION §2 step 3 measures it, against the\ndeclared capacity",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F7.%20Qualification%20of%20frames%20and%20of%20the%20method%2FFrame%20qualification",
          "start_line": 581
        }
      ],
      "key": "frame_fit",
      "label": "Frame fit"
    },
    {
      "conditions": [
        "Actual-use evidence concerns the declared actor class, tasks and conditions."
      ],
      "definition": "Adequate operation of the frame, established only by actual use assessed against expectations recorded from governing sources before results are opened.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 590,
          "quote": "Whether the actor class\noperates the frame adequately is adequate attention, and only actual-use\nevidence establishes it",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F7.%20Qualification%20of%20frames%20and%20of%20the%20method%2FFrame%20qualification",
          "start_line": 585
        }
      ],
      "key": "adequate_attention",
      "label": "Adequate attention"
    },
    {
      "conditions": [],
      "definition": "Qualification of the method by the same process it applies elsewhere, consuming the work boundary, construction/assessment relation and layered sufficiency. It creates no second qualification process.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 608,
          "quote": "The method is qualified the way it qualifies anything else. Qualification\nof generic method sufficiency consumes the work boundary (FOUNDATIONS §2),\nthe construction and assessment relation of ACTIVATION §1 and the layered\nsufficiency of §6; it creates no second process.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/EVALUATION.md#EVALUATION%2F7.%20Qualification%20of%20frames%20and%20of%20the%20method%2FMethod%20self-qualification",
          "start_line": 605
        }
      ],
      "key": "method_self_qualification",
      "label": "Method self-qualification"
    },
    {
      "conditions": [],
      "definition": "Every function and failure relation the method claims: declare, activate, evaluate, conjoin, translate, audit_coverage, revise, result consumption and material composition, each with required representative observations. These are described source operations, not operations performed by this interpretation.",
      "exceptions": [],
      "grounding": [
        {
